async function openUser(name,push=true){name=String(name).toLowerCase();if(push&&pathUser()!==name)history.pushState({},'','/@'+name);
if(S.tab!=='user')S.back=S.tab;S.tab='user';document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('on',!!ME&&name===ME.username&&b.dataset.t==='profile'));
S.up={username:name,loading:true};$('#m').innerHTML='<div class="page">'+userHtml()+'</div>';scrollTo(0,0);
const stale=()=>S.tab!=='user'||!S.up||S.up.username!==name;
try{const r=await FX_DB.from('profiles').select('id,username,display_name,avatar_url,banner_url,bio,novas,level,created_at,flair,border,lifetime_novas').eq('username',name).eq('onboarded',true).maybeSingle();if(stale())return;
if(r.error)S.up={username:name,err:r.error.message};else if(!r.data)S.up={username:name};
else{const id=r.data.id;
const[a,b,pp,,,fv]=await Promise.all([FX_DB.from('follows').select('*',{count:'exact',head:true}).eq('followee',id),FX_DB.from('follows').select('*',{count:'exact',head:true}).eq('follower',id),FX_DB.from('posts').select(POSTSEL).eq('user_id',id).order('created_at',{ascending:false}).limit(30),S.fp,loadStats(id,true),FX_DB.from('user_favs').select('kind,name').eq('user_id',id)]);if(stale())return;
const fd=fv&&!fv.error&&fv.data?fv.data:[];
S.up={username:name,prof:r.data,fc:{r:a.count||0,g:b.count||0},posts:pp.error?[]:pp.data,favs:{T:fd.filter(x=>x.kind==='team').map(x=>x.name),F:fd.filter(x=>x.kind==='fighter').map(x=>x.name)}}}}
catch(e){if(stale())return;S.up={username:name,err:String(e.message||e)}}
$('#m').innerHTML='<div class="page">'+userHtml()+'</div>'}
