if(S.up&&S.up.prof&&S.up.prof.id===id&&S.up.fc){S.up.fc.r=Math.max(0,S.up.fc.r+(had?-1:1));const x=$('#ufr');if(x)x.textContent=S.up.fc.r}
if(ME.fc)ME.fc.g=Math.max(0,(ME.fc.g||0)+(had?-1:1));
