/* ===== DAILY SP: free 25 SP every day (needs supabase/daily.sql) ===== */
let DAILY=null;
function age18(){try{return localStorage.getItem('fx-18')==='1'}catch(e){return false}}
document.addEventListener('click',e=>{if(!e.target.closest('[data-age18]'))return;try{localStorage.setItem('fx-18','1')}catch(x){}try{FX_DB.auth.updateUser({data:{age_confirmed:true}})}catch(x){}go('community')});
function dailyCard(cat){if(!ME)return '';let d='';
if(DAILY&&!DAILY.err){const t=DAILY.next?new Date(DAILY.next).getTime():0,ms=t?t-(Date.now()+(DAILY.skew||0)):0;
if(DAILY.available||ms<=0)d=`<div class="rw-row row sp"><div><b>Daily SP</b><div class="mu">Free 500 SP every day. Busted? Come back tomorrow.</div></div><button class="pri" data-daily style="padding:8px 18px;min-height:40px">Claim 500</button></div>`;
else{const h=Math.floor(ms/36e5),mi=Math.max(1,Math.ceil(ms%36e5/6e4)),h2=mi===60?h+1:h,m2=mi===60?0:mi;d=`<div class="rw-row row sp"><div><b>Daily SP claimed</b><div class="mu">Next 500 SP in ${h2}h ${m2}m</div></div><span class="chip glass">✓ Done</span></div>`}}
if(cat==='daily')return `<div class="glass card rw"><div class="rw-h">Daily points</div>${d||'<p class="mu">Daily SP is unavailable right now.</p>'}</div><p class="mu" style="margin:10px 2px">Claim 500 free SP every 24 hours. Use it to pick winners, spin slots or shop.</p>`;
if(!age18())return `<div class="glass card rw"><div class="rw-h">Slots</div><p class="mu" style="margin:6px 0 12px">Slots are for adults only. Confirm you are 18 or older to play.</p><button class="pri" data-age18 style="padding:8px 18px;min-height:40px">I am 18 or older</button></div>`;
return `<div class="glass card rw"><div class="rw-h">Slots</div><div class="rw-row row sp"><div><b>Sidelyne Slots</b><div class="mu">Pick your machine, set your bet and spin. 3 bonus symbols = free spins.</div></div><button class="pri" data-slots style="padding:8px 18px;min-height:40px">Play</button></div></div>`}
async function loadDaily(){if(!FX_DB||!ME)return;try{const r=await FX_DB.rpc('daily_status');if(r.error)throw r.error;DAILY=r.data;DAILY.skew=r.data.now?new Date(r.data.now).getTime()-Date.now():0}catch(e){DAILY={err:1}}if(S.tab==='community'&&S.hc==='daily'&&!document.querySelector('.modal'))repaint()}
async function claimDaily(btn){if(btn){btn.disabled=true;btn.textContent='Claiming…'}try{const r=await FX_DB.rpc('claim_daily');if(r.error)throw r.error;DAILY={available:false,next:r.data.next,skew:0};if(r.data.claimed)applyNovas(r.data.novas,'Daily SP');else{applyNovas(r.data.novas,null);toast('Already claimed today')}}catch(e){toast('Could not claim: '+(e.message||e))}loadDaily()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-daily]');if(b)claimDaily(b)});
setInterval(()=>{if(!ME||!DAILY||DAILY.err)return;if(DAILY.available===false&&DAILY.next&&Date.now()+(DAILY.skew||0)>=new Date(DAILY.next))loadDaily();else if(S.tab==='community'&&S.hc==='daily'&&!document.querySelector('.modal'))repaint()},30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&ME)loadDaily()});

document.addEventListener('click',e=>{const c=e.target.closest('[data-hc]');if(!c)return;S.hc=c.dataset.hc;go('community');if(S.hc==='daily')loadDaily()});
(function(){var c=document.createElement('style');c.textContent='.rp-h{display:flex;justify-content:space-between;align-items:baseline;gap:10px}.rp{padding:12px 0;border-top:1px solid var(--bd)}.rp:first-child{border-top:0}.rp-top{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:4px}.rp-sp{font-size:11px;font-weight:800;letter-spacing:.08em;color:var(--mu)}.rp-s{font-size:12px;font-weight:800;padding:3px 10px;border-radius:999px;background:var(--sf2);color:var(--mu);white-space:nowrap}.rp-s.w{background:color-mix(in srgb,var(--ok) 18%,transparent);color:var(--ok)}.rp-s.l{background:color-mix(in srgb,var(--bad) 16%,transparent);color:var(--bad)}.rp-m{font-weight:700;overflow-wrap:anywhere}.rp-p{color:var(--mu);font-size:13px;margin-top:2px}.rp-p b{color:var(--tx)}';document.head.appendChild(c)})();

/* fighter photo hydrator: finds letter crests for UFC fighters and swaps in a real headshot */
(()=>{const bad=new Set(),busy=new Set(),queue=[];let run=0,tm=0;
const save=()=>{try{const k=Object.keys(FH);if(k.length>600)k.slice(0,k.length-600).forEach(x=>delete FH[x]);localStorage.setItem('fx-fh',JSON.stringify(FH))}catch(e){}};
const swap=()=>document.querySelectorAll('svg[data-fn]').forEach(el=>{const n=el.dataset.fn;if(FH[nm(n)]){const h=crest(n,el.dataset.sp||'UFC',+el.getAttribute('width')||40);if(h.indexOf('data-fn')<0)el.outerHTML=h}});
const still=n=>[...document.querySelectorAll('svg[data-fn]')].some(e=>e.dataset.fn===n);
function pump(){while(run<4&&queue.length){const n=queue.shift(),k=nm(n);if(!still(n)){busy.delete(k);continue}run++;
fetch('/.netlify/functions/fighter?lite=1&name='+encodeURIComponent(n)).then(r=>r.ok?r.json():null).then(j=>{if(j&&j.headshot){FH[k]='h'+j.headshot;save();swap()}else bad.add(k)}).catch(()=>bad.add(k)).finally(()=>{run--;busy.delete(k);pump()})}}
function scan(){document.querySelectorAll('svg[data-fn]').forEach(el=>{const n=el.dataset.fn,k=nm(n);if(FH[k]||bad.has(k)||busy.has(k))return;busy.add(k);queue.push(n)});swap();pump()}
new MutationObserver(()=>{clearTimeout(tm);tm=setTimeout(scan,120)}).observe(document.body,{childList:true,subtree:true});
setTimeout(scan,500)})();

/* ===== PROFILE > PICKS: every pick, filter by payout status and by sport type ===== */
const pkGroup=sp=>sp==='UFC'||sp==='PFL'?'fight':sp==='NHL'?'hockey':'ball';
const PKG={ball:'Ball sports',hockey:'Hockey',fight:'Fights'};
function picksTab(){
const st=S.pkst||'all',sf=S.pksp||'all',n=S.pkn||15;
const all=Object.entries(S.preds).reverse().map(([k,v])=>{const g=G.find(x=>String(x.id)===String(k)),m=S.pm[k]||{},r=S.res[k],sp=g?g.sp:(m.sp||'');
let state='open';if(r)state=r.r==='win'?'paid':r.r==='loss'&&r.s>0?'lost':'other';
return{k,v,g,m,r,sp,state,grp:pkGroup(sp),t:g?g.a+' vs '+g.b:(m.m||'Game '+k)}});
const cnt=f=>all.filter(f).length;
const stOpts=[['all','All',all.length],['open','Pending',cnt(x=>x.state==='open')],['paid','Paid out',cnt(x=>x.state==='paid')],['lost','Lost',cnt(x=>x.state==='lost')]];
const spOpts=[['all','All sports',all.length],...Object.keys(PKG).map(k=>[k,PKG[k],cnt(x=>x.grp===k)]).filter(o=>o[2]>0)];
let L=all.filter(x=>(st==='all'||x.state===st)&&(sf==='all'||x.grp===sf));
const W=L.filter(x=>x.state==='paid').length,Lo=L.filter(x=>x.state==='lost').length,paidSP=L.filter(x=>x.state==='paid').reduce((a,x)=>a+x.r.a,0);
const row=x=>{const{g,r,v}=x;let s='<span class="rp-s">Pending</span>';
if(r){s=r.r==='win'?'<span class="rp-s w">Paid out '+r.a.toLocaleString()+' SP</span>':r.r==='loss'?(r.s>0?'<span class="rp-s l">Lost −'+r.s.toLocaleString()+' SP</span>':'<span class="rp-s">Played +'+r.a+' SP</span>'):'<span class="rp-s">Refunded</span>'}
else if(g&&g.st==='final')s='<span class="rp-s">Scoring…</span>';
return`<div class="rp"><div class="rp-top"><span class="rp-sp">${esc(x.sp)}</span>${s}</div><div class="rp-m">${esc(x.t)}</div><div class="rp-p">Picked <b>${esc(v)}</b></div></div>`};
const chips=(opts,cur,attr)=>`<div class="row hs">${opts.map(o=>`<button class="chip ${cur===o[0]?'on':''}" ${attr}="${o[0]}">${o[1]} <span class="pf-n">${o[2]}</span></button>`).join('')}</div>`;
const shown=L.slice(0,n);
return`<div class="glass card"><div class="rp-h"><b>My picks</b>${W+Lo?`<span class="mu">${W}W · ${Lo}L${paidSP?' · '+paidSP.toLocaleString()+' SP paid':''}</span>`:''}</div>${chips(stOpts,st,'data-pkst')}${spOpts.length>2?chips(spOpts,sf,'data-pksp'):''}<div style="margin-top:6px">${shown.map(row).join('')||'<p class="mu">'+(all.length?'No picks match this filter.':'No picks yet — try the Picks tab.')+'</p>'}</div>${L.length>n?`<button class="chip" data-pkmore style="display:block;margin:10px auto 0">Show more (${L.length-n} left)</button>`:''}</div>`}
